import{_ as t,o,c as a,a2 as r}from"./chunks/framework.BM5YPQmL.js";const g=JSON.parse('{"title":"Studio UI & Playground Guide","description":"","frontmatter":{},"headers":[],"relativePath":"studio/playground-and-metrics.md","filePath":"studio/playground-and-metrics.md","lastUpdated":null}'),i={name:"studio/playground-and-metrics.md"};function n(s,e,l,d,c,p){return o(),a("div",null,[...e[0]||(e[0]=[r(`<h1 id="studio-ui-playground-guide" tabindex="-1">Studio UI &amp; Playground Guide <a class="header-anchor" href="#studio-ui-playground-guide" aria-label="Permalink to &quot;Studio UI &amp; Playground Guide&quot;">​</a></h1><p><strong>Geomilli Studio</strong> is the unified developer console and operations cockpit for Geomilli, served at <code>http://localhost:3000</code>.</p><hr><h2 id="_1-interactive-api-playground-tab" tabindex="-1">1. Interactive API Playground Tab <a class="header-anchor" href="#_1-interactive-api-playground-tab" aria-label="Permalink to &quot;1. Interactive API Playground Tab&quot;">​</a></h2><p>The Playground lets you test and visualize every endpoint using live MapLibre GL maps with zero external API keys.</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Mode[&quot;Select Mode&lt;br/&gt;(Autocomplete / Nearby / BBox)&quot;] --&gt; Map[&quot;Interactive Map&lt;br/&gt;(Click or Pan/Zoom)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Map --&gt; Request[&quot;Live Query Execution&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Request --&gt; Inspector[&quot;cURL Generator + JSON Inspector + Latency Pill&quot;]</span></span></code></pre></div><h3 id="modes-supported" tabindex="-1">Modes Supported: <a class="header-anchor" href="#modes-supported" aria-label="Permalink to &quot;Modes Supported:&quot;">​</a></h3><ol><li><strong>Autocomplete</strong>: Test keystroke response times with prefix matching, language switches (<code>en</code>, <code>fr</code>, <code>nl</code>), and taxonomy class filters.</li><li><strong>Search &amp; Facets</strong>: Explore faceted distributions (e.g., star ratings, cuisines) with real-time checkbox filtering and custom sort orders.</li><li><strong>Reverse Geocoding</strong>: Click anywhere on the map to drop a pin. The UI renders the enclosing administrative hierarchy and nearest street address.</li><li><strong>Nearby POIs (Radius)</strong>: Drag a slider to set radius (e.g. 500m to 5km). A circular boundary renders on the map highlighting all contained places.</li><li><strong>Bounding Box (Viewport)</strong>: Pan and zoom across the map. As the viewport changes, places inside the bounding box stream into the view.</li><li><strong>Airports &amp; Entity Details</strong>: Search by 3-letter IATA code (<code>BRU</code>, <code>LHR</code>, <code>JFK</code>) or inspect complete OSM and Wikidata tags.</li></ol><h3 id="developer-features" tabindex="-1">Developer Features: <a class="header-anchor" href="#developer-features" aria-label="Permalink to &quot;Developer Features:&quot;">​</a></h3><ul><li><strong>One-Click cURL</strong>: Generates the exact <code>curl</code> command with URL-encoded parameters for your terminal.</li><li><strong>Latency Pill</strong>: Highlights Meilisearch query execution time (e.g. <code>2.8 ms</code>) and total HTTP roundtrip.</li><li><strong>Raw JSON Inspector</strong>: Formatted JSON response with syntax highlighting and copy-to-clipboard.</li></ul><hr><h2 id="_2-importer-control-center-tab" tabindex="-1">2. Importer Control Center Tab <a class="header-anchor" href="#_2-importer-control-center-tab" aria-label="Permalink to &quot;2. Importer Control Center Tab&quot;">​</a></h2><p>Monitor background streaming ingestion jobs in real time:</p><ul><li><strong>Pipeline Stage Visualizer</strong>: Displays active state across <code>Fetch</code> ➔ <code>Filter</code> ➔ <code>Transform</code> ➔ <code>Enrich</code> ➔ <code>Index</code> ➔ <code>Swap</code>.</li><li><strong>Dynamic Country Manager</strong>: Browse all Geofabrik countries. Select additional countries (e.g., <code>Netherlands (NL)</code>, <code>Luxembourg (LU)</code>) and click <strong>&quot;Import Selected Countries&quot;</strong> to queue new ingestion jobs without restarting the server.</li><li><strong>Resource Efficiency Gauges</strong>: <ul><li><strong>Go Heap RSS</strong>: Monitors harvester memory, verifying it stays below 50 MB.</li><li><strong>Disk Staging</strong>: Displays current temporary disk footprint.</li><li><strong>SQLite Cache</strong>: Hits vs. misses for Wikidata entity enrichment.</li></ul></li><li><strong>Live Terminal Logs</strong>: Real-time SSE streaming log viewer.</li></ul><hr><h2 id="_3-metrics-telemetry-tab" tabindex="-1">3. Metrics &amp; Telemetry Tab <a class="header-anchor" href="#_3-metrics-telemetry-tab" aria-label="Permalink to &quot;3. Metrics &amp; Telemetry Tab&quot;">​</a></h2><p>Tracks production health and query performance:</p><ul><li><strong>Connection Badge</strong>: Shows whether connected to <strong>Local Meilisearch</strong> or <strong>Meilisearch Cloud</strong>, index document count, and database size on disk.</li><li><strong>Traffic &amp; Latency Percentiles</strong>: Live charts tracking QPS alongside <code>p50</code>, <code>p95</code>, and <code>p99</code> latency.</li><li><strong>Endpoint Breakdown</strong>: Distribution of calls across <code>/autocomplete</code>, <code>/search</code>, <code>/reverse</code>, and <code>/nearby</code>.</li><li><strong>Top Queries &amp; Zero-Hit Analytics</strong>: Identifies popular searches and queries returning 0 hits to help refine taxonomy or synoynms.</li></ul>`,18)])])}const h=t(i,[["render",n]]);export{g as __pageData,h as default};
